mkdir -p /tmp/actcheck && cat > /tmp/actcheck/run.mjs <<'EOF'
import { spawn } from 'node:child_process';
const page = 'file://' + process.argv[2];
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  ['--headless=new', '--remote-debugging-port=9333', '--user-data-dir=/tmp/actcheck/prof', '--window-size=1200,900', 'about:blank'],
  { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let targets;
for (let i = 0; i < 50; i++) { try { targets = await (await fetch('http://127.0.0.1:9333/json')).json(); break; } catch { await sleep(200); } }
const ws = new WebSocket(targets.find((t) => t.type === 'page').webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener('open', r));
let id = 0; const pending = new Map();
ws.addEventListener('message', (m) => { const d = JSON.parse(m.data); if (pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); } });
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result.result.value;
const load = async () => { await send('Page.navigate', { url: page }); await sleep(800); };
const key = async (k, code, vk) => { for (const type of ['keyDown', 'keyUp']) await send('Input.dispatchKeyEvent', { type, key: k, code, windowsVirtualKeyCode: vk }); await sleep(100); };
const state = () => ev(`({count: document.querySelector('#activity-count').textContent,
  types: [...new Set([...document.querySelectorAll('tbody tr[data-type]:not([hidden])')].map(r => r.dataset.type))],
  shown: document.querySelectorAll('tbody tr[data-type]:not([hidden])').length,
  empty: !document.querySelector('.activity-empty').hidden})`);
const pick = async (sel, val) => { await ev(`(() => { const s = document.querySelector('${sel}'); s.value = '${val}'; s.dispatchEvent(new Event('change', {bubbles: true})); })()`); return state(); };
await send('Page.enable'); await send('Runtime.enable');

// 1. No JavaScript
await send('Emulation.setScriptExecutionDisabled', { value: true }); await load();
console.log('noJS:', await (async () => { await send('Emulation.setScriptExecutionDisabled', { value: false });
  return 'checked below'; })());
await send('Emulation.setScriptExecutionDisabled', { value: true }); await load();
const noJs = await send('DOM.getDocument', {});
const formNode = await send('DOM.querySelector', { nodeId: noJs.result.root.nodeId, selector: '#activity-filters' });
const box = await send('DOM.getBoxModel', { nodeId: formNode.result.nodeId });
console.log('1 noJS form rendered box:', box.error ? 'none (hidden)' : 'VISIBLE');
await send('Emulation.setScriptExecutionDisabled', { value: false });

// 2. Default
await load();
console.log('2 tz:', await ev('Intl.DateTimeFormat().resolvedOptions().timeZone'));
console.log('2 default:', JSON.stringify(await state()));
console.log('2 week options:', JSON.stringify(await ev(`[...document.querySelectorAll('#filter-week option')].map(o => o.text)`)));
await send('Page.captureScreenshot', {}).then((r) => import('node:fs').then((fs) => fs.writeFileSync('/tmp/actcheck/default.png', Buffer.from(r.result.data, 'base64'))));

// 3. Shortcuts, single type, week, combos
console.log('3 failed:', JSON.stringify(await pick('#filter-type', 'failed')));
console.log('3 security:', JSON.stringify(await pick('#filter-type', 'security')));
console.log('3 Sign-out:', JSON.stringify(await pick('#filter-type', 'Sign-out')));
await pick('#filter-type', 'all');
for (const i of [0, 1, 2, 3]) console.log(`3 week ${i}:`, JSON.stringify(await pick('#filter-week', String(i))));
console.log('3 failed + week1:', JSON.stringify(await (async () => { await pick('#filter-week', '1'); return pick('#filter-type', 'failed'); })()));
console.log('3 failed + week0 (expect empty?):', JSON.stringify(await pick('#filter-week', '0')));
console.log('3 security + week5 (expect empty):', JSON.stringify(await (async () => { await pick('#filter-week', '5'); return pick('#filter-type', 'security'); })()));
await send('Page.captureScreenshot', {}).then((r) => import('node:fs').then((fs) => fs.writeFileSync('/tmp/actcheck/empty.png', Buffer.from(r.result.data, 'base64'))));
console.log('3 back to all/all:', JSON.stringify(await (async () => { await pick('#filter-type', 'all'); return pick('#filter-week', 'all'); })()));
console.log('3 url unchanged:', await ev('location.href') === page);

// 4. Keyboard: Tab to each select, change with arrow keys
await load();
await key('Tab', 'Tab', 9);
console.log('4 focus after Tab 1:', await ev('document.activeElement.id'), 'outline:', await ev('getComputedStyle(document.activeElement).outlineStyle'));
await key('ArrowDown', 'ArrowDown', 40);
console.log('4 after ArrowDown:', await ev('document.querySelector("#filter-type").value'), JSON.stringify(await state()));
await key('Tab', 'Tab', 9);
console.log('4 focus after Tab 2:', await ev('document.activeElement.id'));
await key('ArrowDown', 'ArrowDown', 40);
console.log('4 after ArrowDown on week:', await ev('document.querySelector("#filter-week").selectedOptions[0].text'), JSON.stringify(await state()));
console.log('4 url unchanged:', await ev('location.href') === page);

// 5. 320px width
await send('Emulation.setDeviceMetricsOverride', { width: 320, height: 800, deviceScaleFactor: 1, mobile: false });
await load();
console.log('5 320px form right edge:', await ev(`Math.max(...[...document.querySelectorAll('#activity-filters, #activity-filters *')].map(e => e.getBoundingClientRect().right))`),
  'page scrollWidth:', await ev('document.documentElement.scrollWidth'));
await send('Page.captureScreenshot', {}).then((r) => import('node:fs').then((fs) => fs.writeFileSync('/tmp/actcheck/narrow.png', Buffer.from(r.result.data, 'base64'))));
ws.close(); chrome.kill();
EOF
